package io.meridian.cardvault.application;

/**
 * Port to the card keys (GAP-01). Keys are addressed by type, label and version; clear key material never leaves the
 * implementation. Adapters ({@code infrastructure.crypto}):
 *
 * <ul>
 *   <li>{@code EnvelopeHsm}: envelope encryption. Every key is a data key generated by a {@link KeyManagement} master
 *       key (AWS KMS in production, a software master key in development), stored wrapped in
 *       {@code card_vault_key.wrapped_key} with the encryption context tenant + purpose + label/version, unwrapped
 *       on use and cached in memory for a short TTL. Master key rotation re-wraps the data keys (no data
 *       re-encryption). PIN blocks are translated in JVM memory (KMS has no PIN primitives).</li>
 *   <li>{@code Pkcs11Hsm}: keys generated and held inside a PKCS#11 HSM (AWS CloudHSM, Thales Luna) through
 *       SunPKCS11; PIN blocks are translated inside the HSM (unwrap under the zone key into a non-extractable session
 *       object, wrap under the PIN encryption key), so neither the PIN nor the clear PIN block is ever in the JVM.</li>
 * </ul>
 */
public interface Hsm {

    /**
     * A key: {@code type} (CardVaultKeyType), {@code label} and {@code version} name it; {@code wrapped} and
     * {@code masterRef} carry the stored envelope (null for keys inside an HSM and for legacy derived keys).
     * Never use as a map key (arrays compare by identity).
     */
    record KeyRef(String type, String label, int version, byte[] wrapped, String masterRef) {
        public KeyRef(String label, int version) {
            this(null, label, version, null, null);
        }

        /** Stable name of the key (label and version), e.g. {@code pan-dek@<tenant>:v2}. */
        public String name() {
            return label + ":v" + version;
        }
    }

    /** What the vault stores for a key: the wrapped data key (null when held in an HSM), its master key and KCV. */
    record KeyMaterial(byte[] wrapped, String masterRef, String kcv) {}

    /** Creates the key material of a new key (KMS data key, or a key generated inside the HSM). */
    KeyMaterial createKey(KeyRef key);

    /**
     * Master key rotation: the key wrapped under the current master key version. Legacy derived keys (no stored
     * envelope) are adopted, i.e. wrapped for the first time; HSM-held keys come back unchanged.
     */
    KeyMaterial rewrap(KeyRef key);

    /** The master key (version) new data keys are wrapped under, e.g. a KMS key ARN, {@code software:<kcv>}. */
    String currentMasterRef();

    /** AES-256-GCM: returns IV (12 bytes) || ciphertext+tag. {@code aad} binds the ciphertext to its record/field. */
    byte[] encrypt(KeyRef key, byte[] plain, byte[] aad);

    /** Inverse of {@link #encrypt}; throws {@link IllegalStateException} when the blob was tampered with. */
    byte[] decrypt(KeyRef key, byte[] blob, byte[] aad);

    /** Key check value: first 6 hex chars of AES-ECB(key, 16 zero bytes) (HMAC keys: of HMAC-SHA256(key, zeros)). */
    String kcv(KeyRef key);

    /** Keyed fingerprint (hex HMAC-SHA256 under the fingerprint key) of a sensitive value, e.g. the PAN. */
    String fingerprint(KeyRef key, String value);

    /** Deterministic 3-digit CVV2 under the CVK for PAN + expiry (computed on demand; CVV2 is never stored). */
    String deriveCvv(KeyRef cvk, String pan, int month, int year);

    /**
     * PIN translation: unwraps a PIN block sent as base64(IV || AES-GCM ciphertext) under the zone key and returns it
     * encrypted under the PIN encryption key with the deterministic AES key wrap with padding (RFC 5649), the form
     * the vault stores and compares. In HSM mode both steps run inside the HSM. Throws
     * {@link IllegalArgumentException} when the block is malformed or cannot be authenticated under the zone key.
     */
    byte[] translatePinBlock(KeyRef zpk, String wrappedBase64, KeyRef pek, String pan);

    /**
     * A clear reference PIN block (only public values, e.g. the weak-PIN list) encrypted exactly like
     * {@link #translatePinBlock}, so it can be compared with a stored or translated block.
     */
    byte[] protectReferencePinBlock(KeyRef pek, byte[] clearBlock);

    /** PIN encryption key rotation: a stored PIN block re-encrypted from one PIN key to another (inside the HSM). */
    byte[] retranslatePin(KeyRef fromPek, byte[] stored, KeyRef toPek);

    /** True when PIN blocks are only ever clear inside the HSM (PKCS#11 mode). */
    boolean pinInsideHsm();

    /** Adapter and master key description for logs and the health view (never key material). */
    String describe();
}
